return function()
	local PlayerScopeService
	local mockPlayer1
	local mockPlayer2
	local mockServiceProvider
	local mockLoggerManager
	local mockLogger
	local mockScope
	local mockTsPlayerProvider
	local mockPlayerHostedServiceManager
	local mockAsyncTaskCompleted

	beforeEach(function()
		PlayerScopeService = require(script.Parent.PlayerScopeService:Clone())
		mockPlayer1 = {
			UserId = 1,
		}
		mockPlayer2 = {
			UserId = 2,
		}

		mockLogger = {
			verbose = function() end,
		}

		mockLoggerManager = {
			GetLogger = function()
				return mockLogger
			end,
		}

		-- 模拟一个异步任务的PlayerHostedServiceManager
		local PlayerHostedServiceManager = {}
		PlayerHostedServiceManager.__index = PlayerHostedServiceManager

		function PlayerHostedServiceManager.new()
			local self = setmetatable({}, PlayerHostedServiceManager)
			return self
		end

		function PlayerHostedServiceManager:InitAsync() end

		function PlayerHostedServiceManager:Start(cancellationToken)
			-- 模拟一个长时间运行的异步任务
			task.spawn(function(PlayerScopeService, cancellationToken)
				local startTime = os.clock()
				while not cancellationToken.IsCancelled do
					if os.clock() - startTime >= 0.1 then -- 任务正常情况下需要1秒完成
						PlayerScopeService.mockAsyncTaskCompleted = true
						break
					end
					task.wait()
				end
			end, PlayerScopeService, cancellationToken)
		end

		function PlayerHostedServiceManager:Stop()
			-- 模拟停止服务
		end

		local builder = require(game.ReplicatedStorage.Packages.TangSeng.Core.Misc.UnitTestHostBuilderFactory)()
		builder.Services:AddPlayerScopeService()
		builder.Services:AddSingleton("PlayerHostedServiceManager", PlayerHostedServiceManager)
		local host = builder:Build()
		mockServiceProvider = host.Services

		-- 初始化服务
		PlayerScopeService.mockAsyncTaskCompleted = false
		PlayerScopeService.Init(mockServiceProvider, mockLoggerManager,{
			GetCancellationToken = function()
				return {
					IsCancelled = function()
				
					end
				}
			end,
			RemoveCancellationToken = function()
				
			end
			
		})
	end)

	describe("PlayerScopeService", function()
		it("should handle player added correctly", function()
			PlayerScopeService._innerOnPlayerAdded(mockPlayer1)
			PlayerScopeService._innerOnPlayerAdded(mockPlayer2)
		end)

		it("should handle player removing correctly", function()
			-- 先添加玩家
			PlayerScopeService._innerOnPlayerAdded(mockPlayer1)

			-- 触发玩家离开
			PlayerScopeService._innerOnPlayerRemoving(mockPlayer1)
		end)

		it("should clean up scopeCache when player leaves", function()
			-- 先添加玩家
			PlayerScopeService._innerOnPlayerAdded(mockPlayer1)

			-- 验证玩家scope已经被添加
			local cache = PlayerScopeService._innerGetCache()
			expect(cache[mockPlayer1.UserId]).to.be.ok()

			-- 触发玩家离开
			PlayerScopeService._innerOnPlayerRemoving(mockPlayer1)

			-- 等待垃圾回收
			task.wait(0.3)

			-- 验证scope已被清理
			cache = PlayerScopeService._innerGetCache()
			expect(cache[mockPlayer1.UserId]).to.never.be.ok()
		end)

		it("should cancel async tasks when player leaves immediately", function()
			local i = 1
			-- 添加玩家，此时会启动异步任务
			PlayerScopeService._innerOnPlayerAdded(mockPlayer1)

			-- 立即触发玩家离开
			PlayerScopeService._innerOnPlayerRemoving(mockPlayer1)

			-- 等待足够长的时间，让任务有机会完成（如果没有被取消的话）
			task.wait(0.2)

			-- 验证任务没有完成（因为被取消了）
			expect(PlayerScopeService.mockAsyncTaskCompleted).to.equal(false)
		end)

		-- it("should get player scope correctly", function()
		-- 	-- 先添加玩家
		-- 	PlayerScopeService._innerOnPlayerAdded(mockPlayer)

		-- 	-- 测试通过Player对象获取scope
		-- 	local scope1 = PlayerScopeService.GetPlayerScope(mockPlayer)
		-- 	expect(scope1).to.equal(mockScope)

		-- 	-- 测试通过UserId获取scope
		-- 	local scope2 = PlayerScopeService.GetPlayerScope(mockPlayer.UserId)
		-- 	expect(scope2).to.equal(mockScope)
		-- end)

		-- it("should get required service in player scope correctly", function()
		-- 	-- 先添加玩家
		-- 	PlayerScopeService._innerOnPlayerAdded(mockPlayer)

		-- 	-- 测试获取必需服务
		-- 	local service = PlayerScopeService.GetRequiredServiceInPlayerScope(mockPlayer, "ITangSengPlayerProvider")
		-- 	expect(service).to.equal(mockTsPlayerProvider)
		-- end)
	end)
end
